const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const Stripe = require('stripe');

const app = express();
const stripe = Stripe('sk_test_YOUR_SECRET_KEY'); // Replace with your Stripe Secret Key

app.use(cors());
app.use(bodyParser.json());

// Health check
app.get('/', (req, res) => res.send('Paul Coffee backend running...'));

// Create payment link
app.post('/api/create-payment-link', async (req, res) => {
    try {
        const { customer, items, currency, method, mpesaPhone } = req.body;

        if (method === 'visa') {
            const session = await stripe.checkout.sessions.create({
                payment_method_types: ['card'],
                mode: 'payment',
                line_items: items.map(item => ({
                    price_data: {
                        currency: currency.toLowerCase(),
                        product_data: { name: item.name },
                        unit_amount: Math.round(item.price * 100),
                    },
                    quantity: item.quantity,
                })),
                customer_email: customer.email,
                success_url: 'http://localhost:3000/success.html?session_id={CHECKOUT_SESSION_ID}',
                cancel_url: 'http://localhost:3000/cancel.html',
            });
            return res.json({ success: true, paymentUrl: session.url });
        }

        if (method === 'mpesa') {
            // For now, just show instructions
            return res.json({
                success: true,
                message: `Please send ${currency} ${items.reduce((s, i) => s + i.price * i.quantity, 0).toFixed(2)} to M-Pesa number +96598915665`
            });
        }

        if (method === 'bank') {
            return res.json({
                success: true,
                message: `Please transfer to Co-operative Bank of Kenya, Account: 01234566678`
            });
        }

        res.json({ success: false, message: 'Unsupported payment method' });
    } catch (error) {
        console.error('Payment error:', error);
        res.status(500).json({ success: false, message: error.message });
    }
});

app.listen(5000, () => console.log('✅ Backend running on http://localhost:5000'));


